#!/usr/bin/env python3
"""Embeds resources/perlin_en_US.lang into src/client/i18n/BuiltinEnglish.cpp, one C++ string literal per line."""
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SOURCE = os.path.join(ROOT, 'resources/perlin_en_US.lang')
OUTPUT = os.path.join(ROOT, 'src/client/i18n/BuiltinEnglish.cpp')

HEADER = (
    '// Generated by tools/gen_builtin_lang.py from resources/perlin_en_US.lang.\n'
    '#include "client/i18n/BuiltinEnglish.hpp"\n'
    '\n'
    'namespace perlin::i18n {\n'
    '    const char* BuiltinEnglish() {\n'
    '        return\n'
)
FOOTER = '            ;\n    }\n}\n'


def escape(line):
    return line.replace('\\', '\\\\').replace('"', '\\"')


def main():
    with open(SOURCE, encoding='utf8') as f:
        text = f.read()
    lines = [line for line in text.split('\n') if line and not line.startswith('##')]
    body = ''.join('    "%s\\n"\n' % escape(line) for line in lines)
    with open(OUTPUT, 'w', encoding='utf8') as f:
        f.write(HEADER + body + FOOTER)


if __name__ == '__main__':
    main()
